-- GREEN HOME - 02_Du_Lieu_Demo.sql
-- Du lieu mau tu 01_Tao_CSDL.sql cua nhom truong, da dong bo 7 danh muc.
-- FIX: Tao TaiKhoan TRUOC PhanCongCa de thoa trigger TR_PhanCongCa_KiemTra.
-- Chi chay 1 lan tren QuanLyBanHang DA TAO BANG va CHUA NAP DEMO.
-- KHONG DROP database/bang, KHONG xoa hay ghi de du lieu co san.
-- Tai khoan demo_nv1..demo_nv5 co mat khau DANG NHAP 123456 (luu PBKDF2 + salt); chi dung trong demo.

USE QuanLyBanHang;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    IF DB_NAME() <> N'QuanLyBanHang'
        THROW 51090, N'Dang ket noi sai database. Hay chon QuanLyBanHang.', 1;

    IF OBJECT_ID(N'dbo.DanhMuc', N'U') IS NULL
       OR OBJECT_ID(N'dbo.ThuongHieu', N'U') IS NULL
       OR OBJECT_ID(N'dbo.NhanVien', N'U') IS NULL
       OR OBJECT_ID(N'dbo.TaiKhoan', N'U') IS NULL
       OR OBJECT_ID(N'dbo.PhanCongCa', N'U') IS NULL
       OR OBJECT_ID(N'dbo.SanPham', N'U') IS NULL
       OR OBJECT_ID(N'dbo.HoaDon', N'U') IS NULL
       OR OBJECT_ID(N'dbo.ChiTietPhieuDoiTra', N'U') IS NULL
        THROW 51091, N'Thieu bang. Hay chay dung 01_Tao_CSDL.sql truoc.', 1;

    -- Chan chay lai nhieu lan, tranh trung PK va tranh de len du lieu cua ban.
    IF EXISTS (SELECT 1 FROM dbo.DanhMuc)
       OR EXISTS (SELECT 1 FROM dbo.ThuongHieu)
       OR EXISTS (SELECT 1 FROM dbo.KhachHang)
       OR EXISTS (SELECT 1 FROM dbo.NhanVien)
       OR EXISTS (SELECT 1 FROM dbo.CaLamViec)
       OR EXISTS (SELECT 1 FROM dbo.TaiKhoan)
       OR EXISTS (SELECT 1 FROM dbo.PhanCongCa)
       OR EXISTS (SELECT 1 FROM dbo.SanPham)
       OR EXISTS (SELECT 1 FROM dbo.KhuyenMai)
       OR EXISTS (SELECT 1 FROM dbo.SanPhamKhuyenMai)
       OR EXISTS (SELECT 1 FROM dbo.DonHang)
       OR EXISTS (SELECT 1 FROM dbo.ChiTietDonHang)
       OR EXISTS (SELECT 1 FROM dbo.HoaDon)
       OR EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon)
       OR EXISTS (SELECT 1 FROM dbo.PhieuDoiTra)
       OR EXISTS (SELECT 1 FROM dbo.ChiTietPhieuDoiTra)
        THROW 51092, N'Co bang da chua du lieu. Khong nap chong demo; hay sao luu va kiem tra truoc.', 1;

    BEGIN TRANSACTION;

-- ========================= DU LIEU DEMO =========================
-- Tai khoan phai duoc tao truoc khi phan cong ca (trigger TR_PhanCongCa_KiemTra).


-- Kiem tra so luong TRUOC COMMIT: neu INSERT ... SELECT khong tim thay dong,
-- thi thay vi am tham thieu chi tiet doi tra, phai rollback toan bo.
    IF (SELECT COUNT(*) FROM dbo.DanhMuc) <> 7
       OR (SELECT COUNT(*) FROM dbo.ThuongHieu) <> 9
       OR (SELECT COUNT(*) FROM dbo.SanPham) <> 30
       OR (SELECT COUNT(*) FROM dbo.NhanVien) <> 5
       OR (SELECT COUNT(*) FROM dbo.TaiKhoan) <> 5
       OR (SELECT COUNT(*) FROM dbo.PhanCongCa) <> 20
       OR (SELECT COUNT(*) FROM dbo.DonHang) <> 80
       OR (SELECT COUNT(*) FROM dbo.HoaDon) <> 68
       OR (SELECT COUNT(*) FROM dbo.ChiTietHoaDon) <> 200
       OR (SELECT COUNT(*) FROM dbo.PhieuDoiTra) <> 8
       OR (SELECT COUNT(*) FROM dbo.ChiTietPhieuDoiTra) <> 8
        THROW 51093, N'Du lieu demo khong du so luong mong doi. Da huy giao dich.', 1;

    COMMIT TRANSACTION;
    PRINT N'NAP DEMO THANH CONG. Du lieu da COMMIT.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    PRINT N'NAP DEMO THAT BAI. Cac ban ghi trong giao dich da duoc ROLLBACK.';
    THROW;
END CATCH;
GO

-- Kiem tra nhanh sau khi nap: du kien 7 / 9 / 30 / 5 / 5 / 20.
SELECT N'DanhMuc' AS Bang, COUNT(*) AS SoBanGhi FROM dbo.DanhMuc
UNION ALL SELECT N'ThuongHieu', COUNT(*) FROM dbo.ThuongHieu
UNION ALL SELECT N'SanPham', COUNT(*) FROM dbo.SanPham
UNION ALL SELECT N'NhanVien', COUNT(*) FROM dbo.NhanVien
UNION ALL SELECT N'TaiKhoan', COUNT(*) FROM dbo.TaiKhoan
UNION ALL SELECT N'PhanCongCa', COUNT(*) FROM dbo.PhanCongCa
UNION ALL SELECT N'DonHang', COUNT(*) FROM dbo.DonHang
UNION ALL SELECT N'HoaDon', COUNT(*) FROM dbo.HoaDon
UNION ALL SELECT N'ChiTietHoaDon', COUNT(*) FROM dbo.ChiTietHoaDon
UNION ALL SELECT N'PhieuDoiTra', COUNT(*) FROM dbo.PhieuDoiTra
UNION ALL SELECT N'ChiTietPhieuDoiTra', COUNT(*) FROM dbo.ChiTietPhieuDoiTra;
GO
